package search;

import java.util.List;
import java.util.Objects;

public final class DefaultSearchService<T> implements SearchService<T> {
    private final SearchAlgorithm<T> algorithm;

    public DefaultSearchService(SearchAlgorithm<T> algorithm) {
        this.algorithm = Objects.requireNonNull(algorithm, "algorithm must not be null");
    }

    @Override
    public SearchResult search(List<T> sortedValues, T target) {
        return algorithm.search(sortedValues, target);
    }
}

import java.util.Arrays;
import java.util.List;
import search.DefaultSearchService;
import search.SearchAlgorithm;
import search.SearchResult;
import search.SearchService;
import search.SearchStrategyFactory;

class BinarySearchDemo {
    public static void main(String[] args) {
        List<Integer> values = Arrays.asList(2, 3, 4, 10, 40);
        int target = 10;

        SearchAlgorithm<Integer> algorithm = SearchStrategyFactory.linearSearch();
        SearchService<Integer> searchService = new DefaultSearchService<Integer>(algorithm);
        SearchResult result = searchService.search(values, target);
        String message = result.map(
                index -> "Element is present at index " + index,
                () -> "Element is not present in array");

        System.out.println(message);
    }
}

package search;

import java.util.Comparator;
import java.util.Objects;

public final class SearchStrategyFactory {
    private SearchStrategyFactory() {
    }

    public static <T extends Comparable<? super T>> SearchAlgorithm<T> binarySearch() {
        return BinarySearchAlgorithm.naturalOrder();
    }

    public static <T> SearchAlgorithm<T> binarySearch(Comparator<? super T> comparator) {
        return new BinarySearchAlgorithm<T>(Objects.requireNonNull(comparator, "comparator must not be null"));
    }

    public static <T> SearchAlgorithm<T> linearSearch() {
        return new LinearSearchAlgorithm<T>();
    }
}

